import React from 'react';

const MatchScoreCard = ({ score = 0, size = 'small' }) => {
  // Size configurations
  const sizeConfig = {
    small: { width: 60, height: 60, fontSize: 'text-lg', strokeWidth: 4 },
    medium: { width: 80, height: 80, fontSize: 'text-2xl', strokeWidth: 5 },
    large: { width: 120, height: 120, fontSize: 'text-4xl', strokeWidth: 6 }
  };

  const config = sizeConfig[size];
  const radius = (config.width - config.strokeWidth) / 2;
  const circumference = radius * 2 * Math.PI;
  const offset = circumference - (score / 100) * circumference;

  // Color based on score
  const getColor = () => {
    if (score >= 75) return { stroke: '#22c55e', bg: 'bg-green-50', text: 'text-green-600', ring: 'ring-green-200' };
    if (score >= 50) return { stroke: '#eab308', bg: 'bg-yellow-50', text: 'text-yellow-600', ring: 'ring-yellow-200' };
    return { stroke: '#ef4444', bg: 'bg-red-50', text: 'text-red-600', ring: 'ring-red-200' };
  };

  const colors = getColor();

  return (
    <div className={`inline-flex flex-col items-center justify-center ${colors.bg} ${colors.ring} ring-2 rounded-xl p-3 shadow-sm hover:shadow-md transition-all`}>
      {/* Circular Progress */}
      <div className="relative">
        <svg width={config.width} height={config.height} className="transform -rotate-90">
          {/* Background Circle */}
          <circle
            cx={config.width / 2}
            cy={config.height / 2}
            r={radius}
            fill="none"
            stroke="#e5e7eb"
            strokeWidth={config.strokeWidth}
          />
          {/* Progress Circle */}
          <circle
            cx={config.width / 2}
            cy={config.height / 2}
            r={radius}
            fill="none"
            stroke={colors.stroke}
            strokeWidth={config.strokeWidth}
            strokeDasharray={circumference}
            strokeDashoffset={offset}
            strokeLinecap="round"
            className="transition-all duration-1000 ease-out"
          />
        </svg>
        
        {/* Center Text */}
        <div className="absolute inset-0 flex flex-col items-center justify-center">
          <span className={`${config.fontSize} font-black ${colors.text}`}>
            {Math.round(score)}%
          </span>
        </div>
      </div>

      {/* Label */}
      <p className={`text-xs font-semibold ${colors.text} mt-1`}>
        Match
      </p>
    </div>
  );
};

export default MatchScoreCard;
